import React, { useState } from 'react';
import { Card, CardContent } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Avatar, AvatarFallback } from '../ui/avatar';
import {
  Plus,
  Clock,
  Circle,
  Eye,
  Calendar,
  User,
  CheckCircle2,
  GripVertical,
} from 'lucide-react';
import { formatDate } from '../../utils/formatters';

const COLUMNS = [
  { id: 'todo', title: 'Por Hacer', icon: Circle, color: 'bg-gray-100 text-gray-700' },
  { id: 'in_progress', title: 'En Progreso', icon: Clock, color: 'bg-blue-100 text-blue-700' },
  { id: 'review', title: 'En Revisión', icon: Eye, color: 'bg-yellow-100 text-yellow-700' },
  { id: 'completed', title: 'Completado', icon: CheckCircle2, color: 'bg-green-100 text-green-700' },
];

const PRIORITY_COLORS = {
  low: 'bg-gray-100 text-gray-700 border-gray-300',
  medium: 'bg-blue-100 text-blue-700 border-blue-300',
  high: 'bg-orange-100 text-orange-700 border-orange-300',
  urgent: 'bg-red-100 text-red-700 border-red-300',
};

const PRIORITY_LABELS = {
  low: 'Baja',
  medium: 'Media',
  high: 'Alta',
  urgent: 'Urgente',
};

export const KanbanBoard = ({ tasks = [], onTaskClick, onAddTask, onTaskMove, readOnly = false }) => {
  const [draggedTask, setDraggedTask] = useState(null);
  const [dragOverColumn, setDragOverColumn] = useState(null);

  const handleDragStart = (e, task) => {
    if (readOnly) return;
    
    console.log('🎯 Drag Start:', task.title);
    setDraggedTask(task);
    
    // Configurar transferencia de datos
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', task._id);
    
    // Agregar clase de arrastre
    e.currentTarget.classList.add('dragging');
  };

  const handleDragEnd = (e) => {
    console.log('🏁 Drag End');
    e.currentTarget.classList.remove('dragging');
    setDraggedTask(null);
    setDragOverColumn(null);
  };

  const handleDragOver = (e, columnId) => {
    if (!draggedTask || readOnly) return;
    
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = 'move';
    
    setDragOverColumn(columnId);
  };

  const handleDragEnter = (e, columnId) => {
    if (!draggedTask || readOnly) return;
    e.preventDefault();
    setDragOverColumn(columnId);
  };

  const handleDragLeave = (e) => {
    // Solo limpiar si salimos del contenedor principal
    if (e.currentTarget === e.target) {
      setDragOverColumn(null);
    }
  };

  const handleDrop = (e, columnId) => {
    e.preventDefault();
    e.stopPropagation();
    
    console.log('📍 Drop en:', columnId);
    
    if (!draggedTask || readOnly) {
      setDragOverColumn(null);
      return;
    }
    
    // Solo mover si cambió de columna
    if (draggedTask.status !== columnId) {
      console.log('✅ Moviendo tarea:', draggedTask.title, 'a', columnId);
      onTaskMove?.(draggedTask._id, columnId);
    }
    
    setDraggedTask(null);
    setDragOverColumn(null);
  };

  const getTasksByStatus = (status) => {
    return tasks.filter(task => task.status === status);
  };

  const TaskCard = ({ task }) => {
    const completedSubtasks = task.subtasks?.filter(st => st.completed).length || 0;
    const totalSubtasks = task.subtasks?.length || 0;
    const hasSubtasks = totalSubtasks > 0;
    const isDragging = draggedTask?._id === task._id;

    return (
      <div
        draggable={!readOnly}
        onDragStart={(e) => handleDragStart(e, task)}
        onDragEnd={handleDragEnd}
        className={`task-card mb-3 transition-all duration-200 ${
          isDragging ? 'opacity-50 scale-95' : 'opacity-100'
        } ${readOnly ? '' : 'cursor-move hover:shadow-lg'}`}
        style={{
          touchAction: 'none' // Importante para touch devices
        }}
      >
        <Card 
          onClick={() => !isDragging && onTaskClick?.(task)}
          className="cursor-pointer"
        >
          <CardContent className="p-4">
            {/* Drag Handle */}
            {!readOnly && (
              <div className="flex justify-center mb-2 opacity-40 hover:opacity-100 transition-opacity">
                <GripVertical className="w-5 h-5 text-gray-400" />
              </div>
            )}

            {/* Header */}
            <div className="flex items-start justify-between mb-2">
              <div className="flex-1 min-w-0 pr-2">
                <h4 className="font-semibold text-sm mb-1 truncate">
                  {task.title}
                </h4>
                {task.description && (
                  <p className="text-xs text-gray-500 line-clamp-2">
                    {task.description}
                  </p>
                )}
              </div>
              <Badge className={`${PRIORITY_COLORS[task.priority]} text-xs border flex-shrink-0`}>
                {PRIORITY_LABELS[task.priority]}
              </Badge>
            </div>

            {/* Subtasks Progress */}
            {hasSubtasks && (
              <div className="mb-3">
                <div className="flex items-center justify-between text-xs text-gray-600 mb-1">
                  <span>Subtareas</span>
                  <span>{completedSubtasks}/{totalSubtasks}</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-1.5">
                  <div
                    className="bg-green-500 h-1.5 rounded-full transition-all"
                    style={{ width: `${(completedSubtasks / totalSubtasks) * 100}%` }}
                  />
                </div>
              </div>
            )}

            {/* Tags */}
            {task.tags && task.tags.length > 0 && (
              <div className="flex flex-wrap gap-1 mb-3">
                {task.tags.slice(0, 2).map((tag, idx) => (
                  <Badge key={idx} variant="outline" className="text-xs">
                    {tag}
                  </Badge>
                ))}
                {task.tags.length > 2 && (
                  <Badge variant="outline" className="text-xs">
                    +{task.tags.length - 2}
                  </Badge>
                )}
              </div>
            )}

            {/* Footer */}
            <div className="flex items-center justify-between pt-3 border-t">
              {/* Assigned User */}
              <div className="flex items-center space-x-2">
                {task.assigned_to ? (
                  <>
                    <Avatar className="h-6 w-6">
                      <AvatarFallback className="text-xs bg-green-100 text-green-700">
                        {task.assigned_to.full_name?.split(' ').map(n => n[0]).join('').toUpperCase() || '?'}
                      </AvatarFallback>
                    </Avatar>
                    <span className="text-xs text-gray-600 hidden sm:inline">
                      {task.assigned_to.full_name?.split(' ')[0]}
                    </span>
                  </>
                ) : (
                  <div className="flex items-center text-xs text-gray-400">
                    <User className="w-4 h-4 mr-1" />
                    <span className="hidden sm:inline">Sin asignar</span>
                  </div>
                )}
              </div>

              {/* Due Date */}
              {task.due_date && (
                <div className={`flex items-center text-xs ${
                  new Date(task.due_date) < new Date() && task.status !== 'completed'
                    ? 'text-red-600 font-semibold'
                    : 'text-gray-600'
                }`}>
                  <Calendar className="w-3 h-3 mr-1" />
                  <span className="hidden sm:inline">
                    {formatDate(task.due_date)}
                  </span>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    );
  };

  return (
    <div className="kanban-board">
      <style>{`
        .task-card {
          user-select: none;
        }
        
        .task-card.dragging {
          opacity: 0.5;
          transform: scale(0.95);
        }
        
        .kanban-column.drag-over {
          background-color: rgba(16, 185, 129, 0.1);
          border: 2px dashed #10b981;
          transform: scale(1.02);
        }
        
        .kanban-column {
          transition: all 0.2s ease;
        }
        
        .drop-zone-active {
          background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%);
          border: 2px dashed #10b981;
        }
      `}</style>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {COLUMNS.map((column) => {
          const columnTasks = getTasksByStatus(column.id);
          const ColumnIcon = column.icon;
          const isDragOver = dragOverColumn === column.id;

          return (
            <div
              key={column.id}
              className={`kanban-column bg-gray-50 rounded-lg p-4 min-h-[600px] ${
                isDragOver ? 'drag-over drop-zone-active' : ''
              }`}
              onDragOver={(e) => handleDragOver(e, column.id)}
              onDragEnter={(e) => handleDragEnter(e, column.id)}
              onDragLeave={handleDragLeave}
              onDrop={(e) => handleDrop(e, column.id)}
            >
              {/* Column Header */}
              <div className="flex items-center justify-between mb-4 sticky top-0 bg-gray-50 pb-2 z-10">
                <div className="flex items-center space-x-2">
                  <ColumnIcon className="w-5 h-5 text-gray-600" />
                  <h3 className="font-semibold text-sm">{column.title}</h3>
                  <Badge variant="outline" className="text-xs">
                    {columnTasks.length}
                  </Badge>
                </div>
                {!readOnly && column.id === 'todo' && (
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onAddTask?.(column.id)}
                    className="h-7 w-7 p-0 hover:bg-green-100"
                  >
                    <Plus className="w-4 h-4" />
                  </Button>
                )}
              </div>

              {/* Drop Zone Visual */}
              {isDragOver && columnTasks.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-green-600 animate-pulse">
                  <Circle className="w-12 h-12 mb-3" />
                  <p className="font-semibold">Suelta la tarea aquí</p>
                </div>
              )}

              {/* Tasks */}
              <div className="space-y-3">
                {columnTasks.length === 0 && !isDragOver ? (
                  <div className="text-center py-12 text-gray-400 text-sm">
                    {column.id === 'todo' && !readOnly ? (
                      <div>
                        <Circle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p>Arrastra tareas aquí</p>
                        <p className="text-xs mt-1">o crea una nueva</p>
                      </div>
                    ) : (
                      <div>
                        <ColumnIcon className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p>Sin tareas</p>
                      </div>
                    )}
                  </div>
                ) : (
                  columnTasks.map((task) => (
                    <TaskCard key={task._id} task={task} />
                  ))
                )}
              </div>

              {/* Drop Zone Indicator */}
              {isDragOver && columnTasks.length > 0 && (
                <div className="mt-4 p-4 border-2 border-dashed border-green-500 rounded-lg text-center text-green-600 font-semibold animate-pulse">
                  Suelta aquí
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};
